/* CampusFlow: original UI connected to the Express API. */
const THEME = 'campusflow-theme-v1';
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const clean = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => new Date().toLocaleDateString('en-CA');
const addDays = n => { const d=new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate()+n); return d.toLocaleDateString('en-CA'); };
const stamp = () => new Date().toISOString();
const id = prefix => prefix + '-' + Math.random().toString(36).slice(2,8).toUpperCase();
const fmt = d => { if(!d) return '—'; const s = /^\d{4}-\d{2}-\d{2}$/.test(d) ? d+'T12:00:00' : d; const dt=new Date(s); return Number.isNaN(dt.getTime()) ? d : dt.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}); };
const shortDate = d => new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const ago = date => { const diff=Math.max(0,Date.now()-new Date(date).getTime()); if(diff<3600000) return 'Just now'; if(diff<86400000) return Math.floor(diff/3600000)+'h ago'; return Math.floor(diff/86400000)+'d ago'; };
const array = x => Array.isArray(x)?x:[];
const initials = name => name.trim().split(/\s+/).slice(0,2).map(n=>n[0]?.toUpperCase()).join('');
const paths = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',
  shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
  clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 12h6M9 16h6"/>',
  search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
  building:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="M9 7h1M14 7h1M9 11h1M14 11h1M9 15h1M14 15h1M10 22v-4h4v4"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  file:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',
  box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10"/>',
  users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5v1"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
  settings:'<path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4"/><circle cx="12" cy="12" r="5"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  chevron:'<path d="m9 18 6-6-6-6"/>',
  down:'<path d="m6 9 6 6 6-6"/>',
  check:'<path d="m5 12 5 5L20 7"/>',
  close:'<path d="M18 6 6 18M6 6l12 12"/>',
  menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
  logout:'<path d="M10 17l5-5-5-5M15 12H3M12 3h6a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3h-6"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',
  chart:'<path d="M3 20V4M3 20h18M7 16v-4M12 16V7M17 16v-7"/>',
  alert:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/>',
  upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',
  inbox:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 13h5l2 3h4l2-3h5"/>',
  spark:'<path d="m12 2 2 7 7 3-7 2-2 8-3-8-7-2 7-3z"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.65 17.65l1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42M17.65 6.35l1.42-1.42"/>',
  moon:'<path d="M20 15.2A8.7 8.7 0 0 1 8.8 4a8.8 8.8 0 1 0 11.2 11.2Z"/>',
  edit:'<path d="m4 16-1 5 5-1L20 8l-4-4L4 16ZM14 6l4 4"/>',
  trash:'<path d="M4 7h16M10 4h4M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',
  download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',
  mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
  activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
  heart:'<path d="M20.8 8c0 5-8.8 11.5-8.8 11.5S3.2 13 3.2 8A5 5 0 0 1 12 5a5 5 0 0 1 8.8 3Z"/>',
  tag:'<path d="M3 12V4h8l10 10-7 7z"/><circle cx="8" cy="8" r="1"/>',
  book:'<path d="M4 4h13a3 3 0 0 1 3 3v14H7a3 3 0 0 1-3-3V4Zm0 14a3 3 0 0 1 3-3h13"/>',
  monitor:'<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 22h8M12 18v4"/>',
  send:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>',
  return:'<path d="M4 10a8 8 0 1 1 2 8M4 4v6h6"/>',
  checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
  circle:'<circle cx="12" cy="12" r="9"/>',
  eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
  wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M9 16a5 5 0 0 1 6 0M12 20h.01"/>'
};
const icon = (name,size=18,other='') => `<svg ${other} class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.circle}</svg>`;
let db = {users:[],complaints:[],items:[],events:[],rooms:[],bookings:[],notices:[],notifications:[]};
let session = '';
let ui = {page:'overview',modal:null,search:'',status:'All',category:'All',tab:'signin',dark:localStorage.getItem(THEME)==='dark',drawer:false};
let toasts=[];
const current = () => db.users.find(u=>u.id===session) || null;
const admin = () => current()?.role==='admin';
const actor = uid => db.users.find(u=>u.id===uid)?.name || 'Campus member';
function toast(message,kind='success'){const root=$('#toast-root'); if(!root)return;const node=document.createElement('div');node.className='toast '+kind;node.innerHTML=`${icon(kind==='error'?'alert':'checkcircle',18)}<span>${clean(message)}</span>`;root.append(node);setTimeout(()=>node.classList.add('fade'),3500);setTimeout(()=>node.remove(),4000);}
function badge(value){ const v=String(value||''); let tone= 'neutral';if(['Resolved','Approved','Active','Found','Published','Confirmed'].includes(v))tone='green';else if(['In Progress','Pending','Medium','Lost'].includes(v))tone='amber';else if(['Rejected','High','Urgent','Closed'].includes(v))tone='red';else if(['Open','Low','Technology','Academic'].includes(v))tone='blue';return `<span class="badge ${tone}"><span class="badge-dot"></span>${clean(v)}</span>`;}
function countUnread(){return db.notifications.filter(n=>n.userId===session&&!n.read).length;}
function pageConfig(){ return {
  overview:['Dashboard','Your campus, all in one place.'],
  complaints:['Complaint Management','Report issues and track their resolution.'],
  lostfound:['Lost & Found','Reconnect belongings with their owners.'],
  events:['Campus Events','Find experiences happening around campus.'],
  bookings:['Room & Lab Booking','Reserve the right space for your next idea.'],
  notices:['Notice Board','Important announcements, all in one place.'],
  notifications:['Notifications','Stay up to date with your campus activities.'],
  admin:['Admin Console','Manage campus services and requests.'],
  profile:['My Profile','Manage your details and preferences.']
}[ui.page]||['Dashboard','']; }
const navMain=[['overview','grid','Dashboard'],['complaints','clipboard','Complaints'],['lostfound','box','Lost & Found'],['events','calendar','Campus Events'],['bookings','building','Room & Lab Booking'],['notices','file','Notice Board']];
const navManage=[['notifications','bell','Notifications'],['profile','user','My Profile']];
function navLink([page,ico,label]){ return `<button class="nav-link ${ui.page===page?'active':''}" data-page="${page}">${icon(ico,19)}<span>${label}</span>${page==='notifications'&&countUnread()?`<span class="nav-count">${countUnread()}</span>`:''}</button>`; }
function sidebar(){const user=current();return `<aside class="sidebar ${ui.drawer?'sidebar-open':''}">
  <div class="brand"><div class="brand-symbol">${icon('bolt',23)}</div><div class="brand-name">campus<span>flow</span><small>SMART CAMPUS PORTAL</small></div><button class="mobile-close" data-action="drawer-close" aria-label="Close menu">${icon('close')}</button></div>
  <div class="sidebar-body"><div class="nav-label">WORKSPACE</div><nav>${navMain.map(navLink).join('')}</nav><div class="nav-label second-label">YOUR SPACE</div><nav>${navManage.map(navLink).join('')}${admin()?navLink(['admin','shield','Admin Console']):''}</nav></div>
  <div class="sidebar-bottom"><div class="sidebar-help"><span class="help-icon">${icon('spark',18)}</span><div><b>One campus. One place.</b><p>Your everyday services, simplified.</p></div></div><button class="sidebar-user" data-page="profile"><span class="avatar">${clean(initials(user.name))}</span><span class="sidebar-user-copy"><b>${clean(user.name)}</b><small>${user.role==='admin'?'Administrator':user.role==='faculty'?'Faculty member':'Student account'}</small></span>${icon('chevron',16)}</button></div>
  </aside>`;}
function header(){const [title,sub]=pageConfig();const user=current();return `<header class="topbar"><div class="topbar-left"><button class="menu-btn" data-action="drawer-open" aria-label="Open menu">${icon('menu',23)}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${clean(title)}</strong></div></div><div class="topbar-right"><span class="topbar-date">${icon('calendar',16)} ${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</span><button class="icon-btn" data-action="theme" title="Toggle theme" aria-label="Toggle dark mode">${icon(ui.dark?'sun':'moon',19)}</button><button class="icon-btn notif-button" data-page="notifications" aria-label="Notifications">${icon('bell',20)}${countUnread()?'<i></i>':''}</button><button class="header-user" data-page="profile" aria-label="Open profile"><span class="avatar avatar-sm">${clean(initials(user.name))}</span><div class="header-user-name"><b>${clean(user.name)}</b><small>${user.role==='admin'?'Admin':user.role==='faculty'?'Faculty':'Student'}</small></div>${icon('down',14)}</button></div></header>`; }
function heading(actions=''){const [title,sub]=pageConfig();return `<div class="page-heading"><div><p class="eyebrow">CAMPUS SERVICES <span> / ${clean(title.toUpperCase())}</span></p><h1>${clean(title)}</h1><p class="muted heading-sub">${clean(sub)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function btn(label, action, ico='plus', variant='primary', attrs=''){return `<button type="button" class="btn btn-${variant}" data-action="${action}" ${attrs}>${ico?icon(ico,17):''}${label}</button>`;}
function empty(ico,title,description){return `<div class="empty-state"><span class="empty-icon">${icon(ico,28)}</span><h3>${title}</h3><p>${description}</p></div>`;}
function pageShell(){const user=current();if(!user){loginScreen();return;}document.documentElement.dataset.theme=ui.dark?'dark':'light';document.title=pageConfig()[0]+' · CampusFlow';$('#app').innerHTML=`<div class="app-shell">${ui.drawer?'<div class="mobile-scrim" data-action="drawer-close"></div>':''}${sidebar()}<div class="workspace">${header()}<main class="content-scroll"><div class="page-container">${route()}</div><footer class="footer"><span>© ${new Date().getFullYear()} CampusFlow · Smart Campus Service Portal</span><span><span class="live-dot"></span> Campus services · Connected</span></footer></main></div></div>${ui.modal?modalView():''}`; }
function route(){switch(ui.page){case'complaints':return complaintsPage();case'lostfound':return lostPage();case'events':return eventsPage();case'bookings':return bookingPage();case'notices':return noticesPage();case'notifications':return notificationsPage();case'admin':return adminPage();case'profile':return profilePage();default:return overviewPage();}}
function render(preserve=false){const y=preserve?$('.content-scroll')?.scrollTop||0:0;pageShell();if(preserve){const el=$('.content-scroll');if(el)el.scrollTop=y;}else{const el=$('.content-scroll');if(el)el.scrollTop=0;}}
function resetFilters(){ui.search='';ui.status='All';ui.category='All';}
function changePage(page){if(page==='admin'&&!admin()){toast('Admin access is required','error');return;}ui.page=page;ui.modal=null;ui.drawer=false;resetFilters();render();}
function loginScreen(){document.title='Welcome · CampusFlow';document.documentElement.dataset.theme='light';$('#app').innerHTML=`<div class="login-layout"><section class="login-brand-panel"><div class="login-panel-top"><div class="login-brand"><span class="brand-symbol">${icon('bolt',23)}</span><b>campus<span>flow</span></b></div><span class="login-caption">SMART CAMPUS SERVICE PORTAL</span></div><div class="login-panel-content"><span class="hero-pill">${icon('spark',15)} YOUR CAMPUS, REIMAGINED</span><h1>Campus life,<br><em>beautifully</em><br>connected.</h1><p>A smarter way to raise requests, book spaces, explore events, and stay connected to everything happening on campus.</p><div class="login-feature-tags"><span>${icon('checkcircle',15)} One place for services</span><span>${icon('checkcircle',15)} Instant status updates</span></div></div><div class="login-illustration"><div class="art-halo"></div><div class="floating-card art-card-one">${icon('checkcircle',18)} <span>Request resolved <small>Just now</small></span></div><div class="floating-card art-card-two">${icon('calendar',18)} <span>Campus Event <small>Registration confirmed</small></span></div><div class="campus-art"><div class="building-left"></div><div class="building-center"><div class="roof"></div><div class="windows">${Array.from({length:12},()=>'<i></i>').join('')}</div><div class="entrance"></div></div><div class="building-right"></div><div class="art-ground"></div></div></div><div class="login-panel-bottom">Built for students, faculty & campus administrators <span>✦</span> SE Major Project</div></section>
<section class="login-form-panel"><div class="login-form-wrap"><div class="login-top-label"><span class="login-online"><i></i> CAMPUS PORTAL</span><button class="theme-text" data-action="refresh">${icon('return',15)} Refresh connection</button></div><div class="mobile-login-brand">${icon('bolt',21)} campus<span>flow</span></div><div class="auth-heading"><div class="auth-icon">${icon(ui.tab==='register'?'users':'shield',26)}</div><h2>${ui.tab==='register'?'Create your account':'Welcome back!'}</h2><p>${ui.tab==='register'?'Join CampusFlow to access your campus services.':'Sign in to access your campus services.'}</p></div><div class="auth-tabs"><button class="${ui.tab==='signin'?'selected':''}" data-auth-tab="signin">Sign in</button><button class="${ui.tab==='register'?'selected':''}" data-auth-tab="register">Register</button></div>
${ui.tab==='register'?`<form id="register-form" class="auth-form"><label>Full name<input name="name" required maxlength="80" placeholder="Enter your full name" autocomplete="name"></label><label>College email<input type="email" name="email" required placeholder="you@campus.edu" autocomplete="email"></label><label>Department<input name="department" required maxlength="60" placeholder="e.g. Computer Science"></label><label>Password<input type="password" name="password" required minlength="8" placeholder="Minimum 8 characters" autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm" required minlength="8" placeholder="Re-enter password" autocomplete="new-password"></label><button class="btn btn-primary btn-full" type="submit">Create student account ${icon('arrow',18)}</button><p class="auth-note">Create your student account to access campus services from any device.</p></form>`:`<form id="login-form" class="auth-form"><label>Email address<div class="input-icon">${icon('mail',18)}<input name="email" type="email" placeholder="Enter your email" autocomplete="username" required></div></label><label>Password<div class="input-icon">${icon('shield',18)}<input name="password" type="password" placeholder="Enter your password" autocomplete="current-password" required></div></label><button class="btn btn-primary btn-full" type="submit">Sign in to CampusFlow ${icon('arrow',18)}</button></form><div class="demo-divider"><span>OR TRY A DEMO ACCOUNT</span></div><div class="demo-accounts"><button data-demo="student" class="demo-account"><span class="demo-icon student">🎓</span><span><b>Student</b><small>Access everyday services</small></span>${icon('chevron',16)}</button><button data-demo="faculty" class="demo-account"><span class="demo-icon faculty">📘</span><span><b>Faculty</b><small>Manage teaching activities</small></span>${icon('chevron',16)}</button><button data-demo="admin" class="demo-account"><span class="demo-icon admin">🛡️</span><span><b>Administrator</b><small>Manage the entire portal</small></span>${icon('chevron',16)}</button></div><p class="demo-password">All demo accounts use password <strong>Demo@123</strong>.</p>`}</div><div class="login-footer">© ${new Date().getFullYear()} CampusFlow · Smart Campus Service Portal</div></section></div>`;}
function overviewPage(){const user=current();const ownComps=admin()?db.complaints:db.complaints.filter(c=>c.userId===session||c.assignedUserId===session);const ownBookings=admin()?db.bookings:db.bookings.filter(b=>b.userId===session);const upcoming=db.events.filter(e=>e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);const open=ownComps.filter(c=>c.status!=='Resolved'&&c.status!=='Rejected').length;const pending=ownBookings.filter(b=>b.status==='Pending').length;const joined=db.events.filter(e=>e.attendees.includes(session)).length;const recent=ownComps.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,3);const notices=db.notices.slice().sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.date.localeCompare(a.date)).slice(0,3);
return `<div class="overview-heading"><div><p class="eyebrow">YOUR CAMPUS, CONNECTED <span class="hello-wave">✦</span></p><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${clean(user.name.split(' ')[0])} <span class="wave">👋</span></h1><p class="muted">Here's what's happening across your campus today.</p></div><div class="overview-date">${icon('calendar',17)} ${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div></div>
<div class="hero-banner"><div class="hero-content"><span class="hero-kicker">${icon('spark',16)} MAKE CAMPUS LIFE EASIER</span><h2>Everything campus.<br>One simple place.</h2><p>From reporting issues to booking rooms, all the things you need are just a click away.</p></div><div class="hero-visual"><div class="hero-orbit hero-orbit-one"></div><div class="hero-orbit hero-orbit-two"></div><div class="hero-main-icon">${icon('building',88)}</div><div class="hero-float hero-float-top">${icon('checkcircle',24)}<span>All in one</span></div><div class="hero-float hero-float-bottom">${icon('bell',20)}<span>Always updated</span></div></div></div>
<div class="stat-grid"><div class="stat-card"><div class="stat-icon stat-indigo">${icon('clipboard',22)}</div><div class="stat-meta"><span>${admin()?'Total Complaints':'My Complaints'}</span><strong>${ownComps.length.toString().padStart(2,'0')}</strong><small>${open} active request${open===1?'':'s'}</small></div></div><div class="stat-card"><div class="stat-icon stat-orange">${icon('clock',23)}</div><div class="stat-meta"><span>Pending Bookings</span><strong>${pending.toString().padStart(2,'0')}</strong><small>Awaiting approval</small></div></div><div class="stat-card"><div class="stat-icon stat-green">${icon('calendar',23)}</div><div class="stat-meta"><span>${current().role==='student'?'Events Joined':'Upcoming Events'}</span><strong>${(current().role==='student'?joined:db.events.filter(e=>e.date>=today()).length).toString().padStart(2,'0')}</strong><small>${current().role==='student'?'Campus experiences':'Events to explore'}</small></div></div><div class="stat-card"><div class="stat-icon stat-purple">${icon('bell',23)}</div><div class="stat-meta"><span>Unread Notifications</span><strong>${countUnread().toString().padStart(2,'0')}</strong><small>Recent updates</small></div></div></div>
<div class="section-title"><div><h2>Quick access</h2><p>Get things done, faster.</p></div></div><div class="quick-grid">${[
 ['complaints','clipboard','Raise a Complaint','Report an issue','indigo'],['bookings','building',admin()?'Review Bookings':'Book a Room',admin()?'Approve or reject requests':'Find available spaces','orange'],['events','calendar','Explore Events','Something for everyone','green'],['lostfound','search','Lost & Found','Find what matters','purple']
].map(([page,ico,title,desc,tone])=>`<button class="quick-card" data-page="${page}"><span class="quick-icon quick-${tone}">${icon(ico,23)}</span><span class="quick-copy"><strong>${title}</strong><small>${desc}</small></span><span class="quick-arrow">${icon('arrow',17)}</span></button>`).join('')}</div>
<div class="overview-columns"><section class="panel"><div class="panel-title"><div><h2>Upcoming events</h2><p>Don't miss what's around the corner.</p></div><button class="text-link" data-page="events">View all ${icon('arrow',15)}</button></div><div class="compact-event-list">${upcoming.map(e=>`<div class="compact-event"><span class="date-tile"><strong>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{day:'2-digit'})}</strong><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}</small></span><div class="compact-event-main"><b>${clean(e.title)}</b><small>${icon('clock',13)} ${formatTime(e.time)} · ${clean(e.location)}</small></div><button class="round-arrow" data-page="events" title="Explore event">${icon('chevron',18)}</button></div>`).join('')||empty('calendar','No upcoming events','Check again soon.')}</div></section>
<section class="panel"><div class="panel-title"><div><h2>Campus announcements</h2><p>The latest notices and updates.</p></div><button class="text-link" data-page="notices">View all ${icon('arrow',15)}</button></div><div class="compact-notices">${notices.map(n=>`<button class="compact-notice" data-action="notice-view" data-id="${n.id}"><span class="notice-mini-icon">${icon(n.pinned?'alert':'file',19)}</span><span><b>${clean(n.title)}</b><small>${clean(n.category)} · ${ago(n.date)}</small></span>${icon('chevron',15)}</button>`).join('')}</div></section></div>
<div class="overview-columns lower-columns"><section class="panel"><div class="panel-title"><div><h2>${admin()?'Recent campus complaints':'My recent complaints'}</h2><p>Follow requests from start to finish.</p></div><button class="text-link" data-page="complaints">View all ${icon('arrow',15)}</button></div>${recent.length?`<div class="simple-list">${recent.map(c=>`<button class="simple-row" data-action="complaint-view" data-id="${c.id}"><span class="simple-list-icon">${icon('clipboard',19)}</span><span class="simple-list-main"><b>${clean(c.title)}</b><small>${clean(c.id)} · ${fmt(c.createdAt)}</small></span>${badge(c.status)}</button>`).join('')}</div>`:empty('inbox','No complaints yet','Your submitted complaints will appear here.')}</section><section class="panel support-panel"><div class="panel-title"><div><h2>${admin()?'Booking requests to review':'Your room bookings'}</h2><p>${admin()?'Manage campus space approvals.':'Stay updated on your space requests.'}</p></div></div><div class="support-illustration">${icon('calendar',49)}<span class="support-spark-one">✦</span><span class="support-spark-two">✧</span></div><h3>${admin()?`${pending} pending booking${pending===1?'':'s'}`:`${ownBookings.length} booking request${ownBookings.length===1?'':'s'}`}</h3><p>${admin()?'Review pending reservations and approve or reject booking requests.':'Check the status of your room and lab booking requests in one place.'}</p><button class="btn btn-outline" data-page="bookings">${admin()?'Review bookings':'View bookings'} ${icon('arrow',15)}</button></section></div>`;}
function formatTime(t){if(!t)return '';const [h,m]=t.split(':').map(Number);return (h%12||12)+':'+String(m).padStart(2,'0')+(h>=12?' PM':' AM');}
function toolbar(placeholder='Search...',options=null){return `<div class="toolbar"><div class="search-box">${icon('search',19)}<input data-filter="search" placeholder="${clean(placeholder)}" value="${clean(ui.search)}" aria-label="Search"></div>${options?`<div class="filter-wrap">${icon('filter',18)}<select data-filter="status" aria-label="Filter">${options.map(o=>`<option ${ui.status===o?'selected':''}>${clean(o)}</option>`).join('')}</select></div>`:''}</div>`;}
function complaintsPage(){const all=admin()?db.complaints:db.complaints.filter(c=>c.userId===session||c.assignedUserId===session);const filtered=all.filter(c=>(ui.status==='All'||c.status===ui.status)&&(`${c.title} ${c.id} ${c.category} ${c.location}`).toLowerCase().includes(ui.search.toLowerCase()));const stats=[['Total',all.length],['Open',all.filter(c=>c.status==='Open').length],['In Progress',all.filter(c=>c.status==='In Progress').length],['Resolved',all.filter(c=>c.status==='Resolved').length]];
return `${heading(btn('Raise Complaint','complaint-new','plus'))}<div class="mini-stats">${stats.map(([label,v])=>`<div class="mini-stat"><span>${label}</span><strong>${v}</strong></div>`).join('')}</div><section class="panel table-panel"><div class="panel-title"><div><h2>${admin()?'All campus complaints':'My complaints'}</h2><p>Track and manage submitted issues.</p></div>${toolbar('Search complaints...',['All','Open','In Progress','Resolved','Rejected'])}</div><div class="table-scroll"><table><thead><tr><th>COMPLAINT</th><th>CATEGORY</th><th>PRIORITY</th><th>DATE</th><th>STATUS</th><th></th></tr></thead><tbody>${filtered.map(c=>`<tr><td><button class="table-main-link" data-action="complaint-view" data-id="${c.id}">${clean(c.title)}</button><span class="table-sub">${clean(c.id)} · ${clean(c.location)}</span></td><td>${clean(c.category)}</td><td><span class="priority ${c.priority.toLowerCase()}"><i></i>${clean(c.priority)}</span></td><td>${fmt(c.createdAt)}</td><td>${badge(c.status)}</td><td><button class="small-icon-btn" data-action="complaint-view" data-id="${c.id}" title="View details">${icon('chevron',19)}</button></td></tr>`).join('')}</tbody></table>${!filtered.length?empty('inbox','No complaints found','Try another search, or raise a new complaint.'):''}</div></section><div class="subtle-hint">${icon('info',16)} Your request status is updated by campus administrators. Open any complaint to see its details.</div>`;}
function lostPage(){const items=db.items.filter(i=>(ui.status==='All'||ui.status===i.type)&&i.status!=='Closed'&&(`${i.title} ${i.category} ${i.location} ${i.description}`).toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return `${heading(btn('Report an Item','item-new','plus'))}<div class="info-strip"><div class="info-strip-icon">${icon('heart',22)}</div><div><b>Let's get lost things back where they belong.</b><span>Report a lost or found item and help your campus community reconnect with their belongings.</span></div></div><div class="section-filter-bar"><div class="segmented">${['All','Lost','Found'].map(x=>`<button class="${ui.status===x?'selected':''}" data-status="${x}">${x==='All'?'All Items':x+' Items'}</button>`).join('')}</div>${toolbar('Search items...')}</div><div class="items-grid">${items.map(item=>`<article class="item-card"><div class="item-graphic ${item.type.toLowerCase()}"><span>${clean(item.emoji)}</span><span class="item-top-badge">${badge(item.type)}</span></div><div class="item-card-body"><div class="item-card-meta"><span>${icon('calendar',14)} ${fmt(item.date)}</span><span>${clean(item.category)}</span></div><h3>${clean(item.title)}</h3><p>${clean(item.description)}</p><div class="item-location">${icon('pin',16)} ${clean(item.location)}</div><div class="item-card-bottom"><span class="item-author">Posted by ${item.userId===session?'you':clean(actor(item.userId).split(' ')[0])}</span><button class="btn btn-outline btn-small" data-action="item-view" data-id="${item.id}">View details ${icon('arrow',14)}</button></div></div></article>`).join('')}</div>${!items.length?empty('search','Nothing found','Try a different keyword or report an item.'):''}`;}
function eventsPage(){const filtered=db.events.filter(e=>e.date>=today()&&(ui.status==='All'||e.category===ui.status)&&(`${e.title} ${e.location} ${e.description}`).toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));const categories=['All',...new Set(db.events.map(e=>e.category))];return `${heading(admin()?btn('Create Event','event-new','plus'):'')}<div class="event-feature"><div><span class="feature-tag">${icon('spark',15)} DISCOVER · CONNECT · GROW</span><h2>Make memories beyond<br>the classroom.</h2><p>Explore exciting events, workshops, and experiences happening around your campus.</p></div><span class="event-feature-art">🎉</span></div><div class="section-filter-bar"><div class="chip-list">${categories.map(s=>`<button class="chip ${ui.status===s?'selected':''}" data-status="${clean(s)}">${clean(s==='All'?'All events':s)}</button>`).join('')}</div>${toolbar('Search events...')}</div><div class="events-grid">${filtered.map(e=>{const joined=e.attendees.includes(session);const full=e.attendees.length>=e.capacity;return `<article class="event-card"><div class="event-graphic event-${e.color||'blue'}"><span>${clean(e.emoji)}</span><div class="event-date-sticker"><b>${new Date(e.date+'T12:00:00').getDate()}</b><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}</small></div></div><div class="event-card-content"><span class="category-label">${clean(e.category)}</span><h3>${clean(e.title)}</h3><p>${clean(e.description)}</p><div class="event-details"><span>${icon('calendar',16)} ${fmt(e.date)} · ${formatTime(e.time)}</span><span>${icon('pin',16)} ${clean(e.location)}</span><span>${icon('users',16)} ${e.attendees.length}/${e.capacity} registered · ${Math.max(0,e.capacity-e.attendees.length)} seats left</span></div>${current().role==='student'?`<button class="btn ${joined?'btn-light':full?'btn-muted':'btn-primary'} btn-full" data-action="event-register" data-id="${e.id}" ${full&&!joined?'disabled':''}>${joined?`${icon('checkcircle',17)} Registered · Cancel`:full?'Event full':`Register now ${icon('arrow',16)}`}</button>`:`<button class="btn btn-outline btn-full" data-action="event-view" data-id="${e.id}">View event details ${icon('arrow',16)}</button>`}</div></article>`;}).join('')}</div>${!filtered.length?empty('calendar','No events match','Try another category or search.'):''}`;}
function bookingPage(){const rooms=db.rooms.filter(r=>(ui.status==='All'||ui.status===r.type)&&(`${r.name} ${r.building} ${r.equipment}`).toLowerCase().includes(ui.search.toLowerCase()));const own=db.bookings.filter(b=>admin()||b.userId===session).sort((a,b)=>b.date.localeCompare(a.date));const types=['All',...new Set(db.rooms.map(r=>r.type))];return `${heading()}<div class="info-strip booking-strip"><div class="info-strip-icon">${icon('building',23)}</div><div><b>Find the perfect space for your next session.</b><span>${admin()?'Browse campus spaces and approve or reject pending booking requests below. Conflicting reservations are automatically checked.':'Browse rooms, request a time slot, and track approvals. Conflicting reservations are automatically checked.'}</span></div></div><div class="section-title section-spaced"><div><h2>Available spaces</h2><p>Explore classrooms, labs, and meeting spaces.</p></div></div><div class="section-filter-bar"><div class="chip-list">${types.map(t=>`<button class="chip ${ui.status===t?'selected':''}" data-status="${clean(t)}">${clean(t==='All'?'All spaces':t)}</button>`).join('')}</div>${toolbar('Search rooms...')}</div><div class="rooms-grid">${rooms.map(r=>`<article class="room-card"><div class="room-card-top"><div class="room-emoji">${r.emoji}</div><span class="room-type">${clean(r.type)}</span></div><h3>${clean(r.name)}</h3><p class="room-location">${icon('pin',15)} ${clean(r.building)}</p><div class="room-details"><span>${icon('users',16)} ${r.capacity} seats</span><span>${icon('monitor',16)} ${clean(r.equipment)}</span></div>${admin()?'':`<button class="btn btn-outline btn-full" data-action="book-room" data-id="${r.id}">Request booking ${icon('arrow',16)}</button>`}</article>`).join('')}</div>${!rooms.length?empty('building','No rooms found','Try clearing your filters.'):''}<section class="panel bookings-panel"><div class="panel-title"><div><h2>${admin()?'Campus booking requests':'My booking requests'}</h2><p>Keep track of upcoming reservations.</p></div></div><div class="table-scroll"><table><thead><tr><th>SPACE</th><th>DATE</th><th>TIME</th><th>PURPOSE</th><th>STATUS</th><th></th></tr></thead><tbody>${own.map(b=>`<tr><td class="table-strong">${clean(db.rooms.find(r=>r.id===b.roomId)?.name||'Unknown room')}</td><td>${fmt(b.date)}</td><td>${formatTime(b.start)} – ${formatTime(b.end)}</td><td>${clean(b.purpose)}</td><td>${badge(b.status)}</td><td>${admin()&&b.status==='Pending'?`<div class="inline-actions"><button data-action="booking-approve" data-id="${b.id}" class="tiny-btn approve">${icon('check',14)} Approve</button><button data-action="booking-reject" data-id="${b.id}" class="tiny-btn reject">Reject</button></div>`:b.userId===session&&b.status==='Pending'?`<button class="link-danger" data-action="booking-cancel" data-id="${b.id}">Cancel</button>`:''}</td></tr>`).join('')}</tbody></table>${!own.length?empty('calendar','No booking requests','Book a room to see it here.'):''}</div></section>`;}
function noticesPage(){const notices=db.notices.filter(n=>(ui.status==='All'||n.category===ui.status)&&(`${n.title} ${n.body}`).toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.date.localeCompare(a.date));return `${heading(admin()?btn('Publish Notice','notice-new','plus'):'')}<div class="section-filter-bar"><div class="chip-list">${['All','Academic','Administrative','Events','Maintenance'].map(s=>`<button class="chip ${ui.status===s?'selected':''}" data-status="${s}">${s==='All'?'All notices':s}</button>`).join('')}</div>${toolbar('Search notices...')}</div><div class="notice-list">${notices.map(n=>`<article class="notice-card"><div class="notice-icon ${n.category.toLowerCase()}">${icon(n.pinned?'alert':'file',23)}</div><div class="notice-content"><div class="notice-meta"><span class="notice-category">${clean(n.category)}</span><span>·</span><span>${fmt(n.date)}</span>${n.pinned?'<span class="pinned">✦ Pinned</span>':''}</div><h3>${clean(n.title)}</h3><p>${clean(n.body)}</p><button class="text-link" data-action="notice-view" data-id="${n.id}">Read notice ${icon('arrow',15)}</button></div>${admin()?`<button class="small-icon-btn trash-btn" data-action="notice-delete" data-id="${n.id}" title="Delete notice">${icon('trash',18)}</button>`:''}</article>`).join('')}</div>${!notices.length?empty('file','No notices found','Try another filter.'):''}`;}
function notificationsPage(){const all=db.notifications.filter(n=>n.userId===session).sort((a,b)=>b.date.localeCompare(a.date));const filtered=all.filter(n=>ui.status==='All'||(ui.status==='Unread'&&!n.read));return `${heading(btn('Mark all read','notifications-read','check','outline'))}<section class="panel notification-panel"><div class="section-filter-bar notif-filter"><div class="segmented">${['All','Unread'].map(s=>`<button class="${ui.status===s?'selected':''}" data-status="${s}">${s==='All'?'All notifications':'Unread'}${s==='Unread'&&countUnread()?` (${countUnread()})`:''}</button>`).join('')}</div></div><div class="notification-list">${filtered.map(n=>`<button class="notification-row ${n.read?'':'unread'}" data-action="notification-read" data-id="${n.id}"><span class="notification-type notification-${n.type}">${icon(n.type==='complaint'?'clipboard':n.type==='event'?'calendar':n.type==='booking'?'building':n.type==='lost'?'box':'bell',21)}</span><span class="notification-copy"><b>${clean(n.title)}</b><span>${clean(n.body)}</span><small>${ago(n.date)}</small></span>${n.read?'':'<i class="unread-dot"></i>'}</button>`).join('')}${!filtered.length?empty('bell','All caught up!','There are no notifications here right now.'):''}</div></section>`;}
function profilePage(){const u=current();return `${heading()}<div class="profile-layout"><section class="panel profile-card"><div class="profile-cover"><span class="profile-avatar">${clean(initials(u.name))}</span></div><div class="profile-card-main"><h2>${clean(u.name)}</h2><p>${clean(u.email)}</p><span class="profile-role">${icon(u.role==='admin'?'shield':'user',15)} ${clean(u.role.charAt(0).toUpperCase()+u.role.slice(1))}</span><div class="profile-info-line">${icon('building',18)} ${clean(u.department||'Department not set')}</div><div class="profile-info-line">${icon('book',18)} ${clean(u.year||'Campus member')}</div><button class="btn btn-outline btn-full" data-action="logout">${icon('logout',16)} Sign out</button></div></section><section class="panel profile-edit"><div class="panel-title"><div><h2>Personal information</h2><p>Keep your campus profile up to date.</p></div></div><form id="profile-form" class="form-grid"><label class="field">Full name<input name="name" value="${clean(u.name)}" required maxlength="80"></label><label class="field">Email address<input value="${clean(u.email)}" disabled><small>Contact an administrator to change your sign-in email.</small></label><label class="field">Department<input name="department" value="${clean(u.department||'')}" maxlength="60" required></label><label class="field">Year / Designation<input name="year" value="${clean(u.year||'')}" maxlength="50"></label><label class="field">Phone (optional)<input name="phone" type="tel" value="${clean(u.phone||'')}" maxlength="18" placeholder="Add a phone number"></label><div class="form-full"><button class="btn btn-primary" type="submit">${icon('check',16)} Save changes</button></div></form></section></div><section class="panel preference-panel"><div><div class="pref-icon">${icon('sun',22)}</div><div><h3>Appearance</h3><p>Switch between light and dark theme.</p></div></div><button class="btn btn-outline" data-action="theme">${icon(ui.dark?'sun':'moon',17)} ${ui.dark?'Use light theme':'Use dark theme'}</button></section>`;}
function adminPage(){if(!admin())return empty('shield','Not authorized','Sign in as an administrator.');const issues=db.complaints.filter(c=>c.status==='Open').length,pending=db.bookings.filter(b=>b.status==='Pending').length,claims=db.items.reduce((n,i)=>n+i.claims.filter(c=>c.status==='Pending').length,0);return `${heading(btn('Export CSV Report','export','download','outline'))}<div class="stat-grid admin-stats"><div class="stat-card"><div class="stat-icon stat-indigo">${icon('users',22)}</div><div class="stat-meta"><span>Total Users</span><strong>${db.users.length}</strong><small>Portal accounts</small></div></div><div class="stat-card"><div class="stat-icon stat-orange">${icon('alert',23)}</div><div class="stat-meta"><span>Open Complaints</span><strong>${issues}</strong><small>Need attention</small></div></div><div class="stat-card"><div class="stat-icon stat-purple">${icon('building',23)}</div><div class="stat-meta"><span>Pending Bookings</span><strong>${pending}</strong><small>Awaiting review</small></div></div><div class="stat-card"><div class="stat-icon stat-green">${icon('box',23)}</div><div class="stat-meta"><span>Claim Requests</span><strong>${claims}</strong><small>Pending verification</small></div></div></div><div class="admin-tabs">${[['complaints','Complaints'],['bookings','Bookings'],['claims','Item Claims'],['users','Users']].map(([s,title])=>`<button class="${ui.status===s||(ui.status==='All'&&s==='complaints')?'selected':''}" data-admin-tab="${s}">${title}</button>`).join('')}</div>${adminTable(ui.status==='All'?'complaints':ui.status)}`;}
function adminTable(tab){if(tab==='bookings')return `<section class="panel table-panel"><div class="panel-title"><div><h2>Booking approvals</h2><p>Review time slots before confirming reservations.</p></div></div><div class="table-scroll"><table><thead><tr><th>REQUEST</th><th>REQUESTED BY</th><th>DATE & TIME</th><th>PURPOSE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${db.bookings.slice().sort((a,b)=>Number(a.status!=='Pending')-Number(b.status!=='Pending')).map(b=>`<tr><td class="table-strong">${clean(db.rooms.find(r=>r.id===b.roomId)?.name||'Room')}<span class="table-sub">${clean(b.id)}</span></td><td>${clean(actor(b.userId))}</td><td>${fmt(b.date)}<span class="table-sub">${formatTime(b.start)} – ${formatTime(b.end)}</span></td><td>${clean(b.purpose)}</td><td>${badge(b.status)}</td><td>${b.status==='Pending'?`<div class="inline-actions"><button data-action="booking-approve" data-id="${b.id}" class="tiny-btn approve">${icon('check',14)} Approve</button><button data-action="booking-reject" data-id="${b.id}" class="tiny-btn reject">Reject</button></div>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`;
if(tab==='claims'){const claims=db.items.flatMap(i=>i.claims.map(c=>({...c,item:i}))).sort((a,b)=>Number(a.status!=='Pending')-Number(b.status!=='Pending'));return `<section class="panel table-panel"><div class="panel-title"><div><h2>Lost & Found claims</h2><p>Verify ownership before releasing found items.</p></div></div><div class="table-scroll"><table><thead><tr><th>ITEM</th><th>CLAIMANT</th><th>OWNERSHIP DETAILS</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${claims.map(c=>`<tr><td class="table-strong">${clean(c.item.title)}<span class="table-sub">${clean(c.item.id)}</span></td><td>${clean(actor(c.userId))}</td><td class="description-col">${clean(c.proof)}</td><td>${badge(c.status)}</td><td>${c.status==='Pending'?`<div class="inline-actions"><button class="tiny-btn approve" data-action="claim-approve" data-id="${c.item.id}" data-claim="${c.id}">${icon('check',14)} Verify</button><button class="tiny-btn reject" data-action="claim-reject" data-id="${c.item.id}" data-claim="${c.id}">Reject</button></div>`:'—'}</td></tr>`).join('')}</tbody></table>${!claims.length?empty('box','No claims submitted','Claim requests will appear here.'):''}</div></section>`;}
if(tab==='users')return `<section class="panel table-panel"><div class="panel-title"><div><h2>Registered users</h2><p>Manage registered campus accounts and their access.</p></div></div><div class="table-scroll"><table><thead><tr><th>USER</th><th>EMAIL</th><th>DEPARTMENT</th><th>ROLE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${db.users.map(u=>`<tr><td><div class="person-cell"><span class="avatar avatar-tiny">${clean(initials(u.name))}</span><b>${clean(u.name)}</b></div></td><td>${clean(u.email)}</td><td>${clean(u.department)}</td><td><select class="role-select" data-user-role="${u.id}" ${u.id===session?'disabled':''}>${['student','faculty','admin'].map(r=>`<option value="${r}" ${r===u.role?'selected':''}>${r[0].toUpperCase()+r.slice(1)}</option>`).join('')}</select></td><td>${badge(u.active===false?'Inactive':'Active')}</td><td>${u.id!==session?`<button class="tiny-btn ${u.active===false?'approve':'reject'}" data-action="user-toggle" data-id="${u.id}">${u.active===false?'Activate':'Deactivate'}</button>`:'You'}</td></tr>`).join('')}</tbody></table></div></section>`;
return `<section class="panel table-panel"><div class="panel-title"><div><h2>Complaint queue</h2><p>Prioritize issues and update their resolution status.</p></div><button class="text-link" data-page="complaints">Full list ${icon('arrow',16)}</button></div><div class="table-scroll"><table><thead><tr><th>COMPLAINT</th><th>REPORTED BY</th><th>PRIORITY</th><th>STATUS</th><th>MANAGE</th></tr></thead><tbody>${db.complaints.slice().sort((a,b)=>Number(a.status==='Resolved')-Number(b.status==='Resolved')).map(c=>`<tr><td><button class="table-main-link" data-action="complaint-view" data-id="${c.id}">${clean(c.title)}</button><span class="table-sub">${clean(c.id)} · ${clean(c.category)}</span></td><td>${clean(actor(c.userId))}</td><td><span class="priority ${c.priority.toLowerCase()}"><i></i>${c.priority}</span></td><td>${badge(c.status)}</td><td><button class="tiny-btn manage" data-action="complaint-manage" data-id="${c.id}">${icon('edit',14)} Update</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function field(label,name,placeholder='',type='text',required=true,extras=''){return `<label class="field">${label}${required?'<span class="required"> *</span>':''}<input name="${name}" type="${type}" placeholder="${clean(placeholder)}" ${required?'required':''} ${extras}></label>`;}
function selectField(label,name,values){return `<label class="field">${label} <span class="required">*</span><select name="${name}" required>${values.map(v=>`<option value="${clean(v)}">${clean(v)}</option>`).join('')}</select></label>`;}
function textareaField(label,name,placeholder='',rows=4){return `<label class="field form-full">${label} <span class="required">*</span><textarea name="${name}" rows="${rows}" placeholder="${clean(placeholder)}" required minlength="5" maxlength="1800"></textarea></label>`;}
function modalFrame(title,subtitle,body,wide=false){return `<div class="modal-overlay" data-action="modal-close-bg"><section class="modal-dialog ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${clean(title)}"><div class="modal-heading"><div><h2>${clean(title)}</h2><p>${clean(subtitle||'')}</p></div><button type="button" class="icon-btn" data-action="modal-close" aria-label="Close dialog">${icon('close',22)}</button></div><div class="modal-content">${body}</div></section></div>`;}
function modalView(){const modal=ui.modal;if(!modal)return '';const type=modal.type;const obj=modal.id;
if(type==='complaint-new')return modalFrame('Raise a complaint','Tell us what needs attention on campus.',`<form id="complaint-form" class="form-grid">${field('Complaint title','title','e.g. Projector not working','text',true,'maxlength="110"')}${selectField('Category','category',['Classroom','Maintenance','IT & Network','Infrastructure','Sanitation','Security','Other'])}${field('Location','location','e.g. Block A, Room 204','text',true,'maxlength="120"')}${selectField('Priority','priority',['Medium','Low','High'])}${textareaField('Description','description','Describe the issue and any useful details...')}<div class="form-full modal-footer"><button class="btn btn-outline" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${icon('send',16)} Submit complaint</button></div></form>`);
if(type==='complaint-view'){const c=db.complaints.find(x=>x.id===obj);if(!c)return '';return modalFrame('Complaint details',c.id,`<div class="detail-header"><h3>${clean(c.title)}</h3>${badge(c.status)}</div><div class="detail-grid"><div><span>Category</span><strong>${clean(c.category)}</strong></div><div><span>Priority</span><strong>${clean(c.priority)}</strong></div><div><span>Location</span><strong>${clean(c.location)}</strong></div><div><span>Submitted</span><strong>${fmt(c.createdAt)}</strong></div><div><span>Assigned to</span><strong>${clean(c.assignedTo||'Unassigned')}</strong></div><div><span>Reported by</span><strong>${clean(actor(c.userId))}</strong></div></div><h4 class="detail-section-title">Issue description</h4><p class="detail-description">${clean(c.description)}</p>${complaintHistory(c)}<div class="status-tracker"><div class="tracker-node active">${icon('check',14)}<span>Submitted</span></div><div class="tracker-line ${c.status!=='Open'?'active':''}"></div><div class="tracker-node ${c.status!=='Open'?'active':''}">${icon('check',14)}<span>In review</span></div><div class="tracker-line ${c.status==='Resolved'?'active':''}"></div><div class="tracker-node ${c.status==='Resolved'?'active':''}">${icon('check',14)}<span>${c.status==='Rejected'?'Rejected':'Resolved'}</span></div></div>${canManageComplaint(c)?`<div class="modal-footer"><button class="btn btn-primary" data-action="complaint-manage" data-id="${c.id}">${icon('edit',16)} Update complaint</button></div>`:''}`);}
if(type==='complaint-manage'){const c=db.complaints.find(x=>x.id===obj);if(!c||!canManageComplaint(c))return '';return modalFrame('Update complaint',c.id+' · '+c.title,`<form id="complaint-update-form" class="form-grid"><input type="hidden" name="id" value="${c.id}">${selectField('Status','status',['Open','In Progress','Resolved','Rejected'])}${selectField('Priority','priority',['Low','Medium','High'])}${field('Assigned team','assignedTo','e.g. Maintenance Team','text',false,'maxlength="80" value="'+clean(c.assignedTo||'')+'"')}${assignmentField(c)}<label class="field form-full">Response / progress note<textarea name="note" rows="3" maxlength="1800" placeholder="Explain the update for the student"></textarea></label><div class="form-full modal-footer"><button class="btn btn-outline" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Save updates ${icon('check',16)}</button></div></form>`.replace(`<option value="${clean(c.status)}">`,`<option value="${clean(c.status)}" selected>`).replace(`<option value="${clean(c.priority)}">`,`<option value="${clean(c.priority)}" selected>`));}
if(type==='item-new')return modalFrame('Report a lost or found item','Help the campus community reconnect belongings.',`<form id="item-form" class="form-grid">${selectField('Report type','type',['Lost','Found'])}${selectField('Category','category',['Electronics','Documents','Personal Items','Stationery','Keys','Clothing','Other'])}${field('Item title','title','e.g. Black wireless headphones','text',true,'maxlength="95"')}${field('Last seen / found location','location','e.g. Central Library','text',true,'maxlength="120"')}${field('Date','date','','date',true,'max="'+today()+'" value="'+today()+'"')}${textareaField('Description','description','Color, brand, identifying details...')}<div class="form-full modal-footer"><button class="btn btn-outline" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${icon('plus',17)} Publish report</button></div></form>`);
if(type==='item-view'){const i=db.items.find(x=>x.id===obj);if(!i)return '';const claimed=i.claims.some(c=>c.userId===session);return modalFrame(i.title,i.id+' · '+i.type+' item',`<div class="item-modal-art">${i.emoji}</div><div class="detail-header">${badge(i.type)} ${badge(i.status)}<span class="muted">${fmt(i.date)}</span></div><div class="detail-grid"><div><span>Category</span><strong>${clean(i.category)}</strong></div><div><span>Location</span><strong>${clean(i.location)}</strong></div><div><span>Reported by</span><strong>${clean(actor(i.userId))}</strong></div></div><h4 class="detail-section-title">Description</h4><p class="detail-description">${clean(i.description)}</p><div class="modal-footer">${i.userId===session&&i.status==='Active'?`<button class="btn btn-outline" data-action="item-close" data-id="${i.id}">${icon('check',16)} Mark resolved</button>`:i.userId!==session&&!claimed&&i.status==='Active'?`<button class="btn btn-primary" data-action="claim-new" data-id="${i.id}">${icon('heart',17)} ${i.type==='Found'?'Request to claim':'I have information'}</button>`:claimed?`<span class="muted">${icon('checkcircle',16)} Your response has been sent for review.</span>`:''}</div>`);}
if(type==='claim-new'){const i=db.items.find(x=>x.id===obj);if(!i||i.userId===session)return '';return modalFrame(i.type==='Found'?'Request item claim':'Share item information',i.title,`<div class="info-strip"><div class="info-strip-icon">${icon('shield',20)}</div><div><b>Verification is required.</b><span>Administrators review responses before marking an item as returned.</span></div></div><form id="claim-form" class="form-grid"><input type="hidden" name="itemId" value="${i.id}">${textareaField(i.type==='Found'?'How can you prove it belongs to you?':'What do you know about this item?','proof','Describe identifying details or useful information...')}<div class="form-full modal-footer"><button class="btn btn-outline" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${icon('send',16)} Submit response</button></div></form>`);}
 if(type==='event-view'&&current()?.role!=='student'){const e=db.events.find(x=>x.id===obj);if(!e)return '';return modalFrame('Event details',e.title,`<div class="detail-header"><h3>${clean(e.title)}</h3><span class="category-label">${clean(e.category)}</span></div><div class="detail-grid"><div><span>Date</span><strong>${fmt(e.date)}</strong></div><div><span>Time</span><strong>${formatTime(e.time)}</strong></div><div><span>Location</span><strong>${clean(e.location)}</strong></div><div><span>Registered participants</span><strong>${e.attendees.length}/${e.capacity}</strong></div></div>${admin()?`<a class="btn btn-outline" href="/api/events/${e.id}/participants.csv">Download participant list</a>`:''}<h4 class="detail-section-title">About this event</h4><p class="detail-description">${clean(e.description)}</p><div class="modal-footer"><button class="btn btn-outline" data-action="modal-close">Close</button></div>`);}
if(type==='event-new'&&admin())return modalFrame('Create campus event','Publish a new event for students and faculty.',`<form id="event-form" class="form-grid">${field('Event title','title','e.g. Robotics Showcase','text',true,'maxlength="100"')}${selectField('Category','category',['Technology','Culture','Workshop','Sports','Career','Other'])}${field('Date','date','','date',true,'min="'+today()+'"')}${field('Start time','time','','time',true)}${field('Venue','location','e.g. Main Auditorium','text',true,'maxlength="90"')}${field('Capacity','capacity','e.g. 100','number',true,'min="1" max="10000"')}${textareaField('Description','description','What can attendees expect?')}<div class="form-full modal-footer"><button type="button" class="btn btn-outline" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">${icon('calendar',17)} Publish event</button></div></form>`);
if(type==='book-room'&&!admin()){const r=db.rooms.find(x=>x.id===obj);if(!r)return '';return modalFrame('Request room booking',r.name+' · '+r.building,`<div class="booking-room-summary"><span>${r.emoji}</span><div><strong>${clean(r.name)}</strong><small>${r.capacity} seats · ${clean(r.equipment)}</small></div></div><form id="booking-form" class="form-grid"><input name="roomId" type="hidden" value="${r.id}">${field('Booking date','date','','date',true,'min="'+today()+'" value="'+addDays(1)+'"')}${field('Start time','start','','time',true,'value="10:00"')}${field('End time','end','','time',true,'value="11:00"')}${field('Purpose','purpose','e.g. Project team meeting','text',true,'maxlength="130"')}<div class="form-full subtle-hint">${icon('info',17)} All bookings require admin approval. Overlapping requests are blocked.</div><div id="availability-info" class="form-full subtle-hint" aria-live="polite">Checking availability…</div><div class="form-full modal-footer"><button type="button" class="btn btn-outline" data-action="modal-close">Cancel</button><button type="submit" class="btn btn-primary">${icon('calendar',17)} Request booking</button></div></form>`);}
if(type==='notice-new'&&admin())return modalFrame('Publish notice','Share an important announcement across campus.',`<form id="notice-form" class="form-grid">${field('Notice title','title','e.g. Updated semester schedule','text',true,'maxlength="140"')}${selectField('Category','category',['Academic','Administrative','Events','Maintenance'])}${textareaField('Announcement','body','Write the notice in clear and simple language...',6)}<label class="form-full checkbox-line"><input type="checkbox" name="pinned"><span>Pin this notice to the top of the board</span></label><div class="form-full modal-footer"><button class="btn btn-outline" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${icon('send',16)} Publish notice</button></div></form>`);
if(type==='notice-view'){const n=db.notices.find(x=>x.id===obj);if(!n)return '';return modalFrame(n.title,`${n.category} · ${fmt(n.date)}`,`<div class="notice-full-body"><span class="notice-full-emoji">📣</span><p>${clean(n.body)}</p></div>`);}
return '';}
function openModal(type,id=null){ui.modal={type,id};render(true);if(type==='book-room')checkAvailability();setTimeout(()=>$('.modal-dialog input:not([type="hidden"]),.modal-dialog select,.modal-dialog textarea')?.focus(),0);}
function closeModal(){ui.modal=null;render(true);}
function requiredTrim(v,label){const value=String(v??'').trim();if(!value)throw Error(label+' is required.');return value;}
function validateDescription(v){const value=requiredTrim(v,'Description');if(value.length<5)throw Error('Please enter at least 5 meaningful characters.');return value;}
function isConflicting(roomId,date,start,end,exclude=null){return db.bookings.some(b=>b.id!==exclude && b.roomId===roomId&&b.date===date&&['Pending','Approved'].includes(b.status)&&start<b.end&&end>b.start);}
